import { getAllProducts } from '../lib/db';
import { cacheTag, revalidateTag } from 'next/cache';

interface Product {
  id: number;
  name: string;
  price: number;
}

// Cached data fetcher using 'use cache' directive
async function getCachedProducts() {
  'use cache';
  cacheTag('products');
  return await getAllProducts() as Product[];
}

// Child component that fetches product data
async function ProductList() {
  const products = await getCachedProducts();

  return (
    <div className="border p-4 rounded-lg shadow-sm mb-6">
      <h2 className="text-xl font-semibold mb-3">Products</h2>
      <ul className="space-y-2">
        {products.map((product) => (
          <li key={product.id} className="flex justify-between items-center p-2 bg-gray-50 rounded">
            <span>{product.name}</span>
            <span className="font-mono font-medium">${product.price}</span>
          </li>
        ))}
      </ul>
      <p className="text-xs text-gray-400 mt-4 text-right">
        Fetched at: {new Date().toLocaleTimeString()}
      </p>
    </div>
  );
}

export default function Page() {
  // Inline server action to invalidate cache
  async function invalidateCache() {
    'use server';
    revalidateTag('products');
  }

  return (
    <div className="max-w-md mx-auto py-10 px-4 font-sans">
      <h1 className="text-2xl font-bold mb-6">Cache Invalidation Demo</h1>

      <ProductList />

      <form action={invalidateCache} className="flex flex-col gap-2">
        <button 
          type="submit" 
          className="bg-blue-600 hover:bg-blue-700 text-white font-medium py-2 px-4 rounded transition-colors"
        >
          Invalidate "products" Cache
        </button>
        <p className="text-sm text-gray-500">
          Submitting this form invalidates the "products" tag. The timestamp above will update on the next render.
        </p>
      </form>
    </div>
  );
}

